class Solution {
  maxSlidingWindow(arr, k) {
    const n = arr.length;
    const stack = [];
    const ans = [];
    for (let i = n - 1; i >= 0; i--) {
      while (stack.length && arr[stack[stack.length - 1]] < arr[i]) {
        stack.pop();
      }
      if (i <= n - k) {
        while (stack.length && stack[0] > i + k - 1) {
          stack.shift();
        }
        ans.push(stack.length ? arr[stack[0]] : arr[i]);
      }
      stack.push(i);
    }
    return ans.reverse();
  }
}

