public class Solution
{
    public List<int> MaxSlidingWindow(List<int> arr, int k)
    {
        // Raj Thomas 4th July 2026 2:43PM IST 
        List<int> result = new List<int>();
        LinkedList<int> dq = new LinkedList<int>();
        int len = arr.Count;

        for(int idx = 0; idx < len; idx++) {

            // remove expired 
            int windowStartIdx = idx - k + 1;
            if(dq.Count > 0 && dq.First.Value < windowStartIdx) {
                dq.RemoveFirst();
            }

            // remove smaller values from dequeue
            while(dq.Count > 0 && arr[dq.Last.Value] <= arr[idx]) {
                dq.RemoveLast();
            }

            // add curr index
            dq.AddLast(idx);

            // check if window is complete 
            if(windowStartIdx >= 0) {
                result.Add(arr[dq.First.Value]);
            }

        }

        return result;
    }
}
